insert into questions (certification_id, domain_id, body, explain, sort_order)
select c.id, d.id, v.body, v.explain, v.sort_order
from (values
    ('saa', 'Cost-optimized architectures', 'A company stores 40 TB of log archives accessed roughly twice a year. Retrieval within 12 hours is acceptable. Which S3 storage class gives the lowest storage cost?', 'Deep Archive is the cheapest class, and its standard retrieval completes within 12 hours, which this workload tolerates. Glacier Flexible Retrieval costs more for the same access pattern.', 0),
    ('saa', 'Secure architectures', 'An application running on EC2 must read objects from an S3 bucket. What is the recommended way to grant access?', 'Instance profiles supply temporary, automatically rotated credentials. Long-lived access keys on disk are the pattern AWS explicitly advises against.', 1),
    ('saa', 'Resilient architectures', 'Which two actions improve the availability of an RDS for MySQL database? (Choose TWO)', 'Multi-AZ provides a synchronous standby with automatic failover inside a Region; a cross-Region read replica can be promoted if a Region is lost. Sizing and backups address performance and recovery, not availability.', 2),
    ('saa', 'High-performing architectures', 'A public web tier handles unpredictable traffic, terminates TLS and routes by URL path. Which combination fits?', 'The ALB is the layer-7 choice for HTTP and HTTPS: it terminates TLS, routes on host and path, and integrates with Auto Scaling target groups.', 3),
    ('saa', 'Resilient architectures', 'Which service decouples a producer from a consumer so that messages survive a consumer outage?', 'SQS retains messages in the queue until a consumer deletes them, so the consumer can be offline without losing work. SNS pushes to subscribers and does not buffer for absent ones.', 4),
    ('saa', 'Secure architectures', 'Instances in a private subnet must download OS patches from the internet but must not be reachable from it. What do you configure?', 'A NAT gateway in a public subnet gives outbound-only IPv4 access to private subnets. Egress-only internet gateways serve the same purpose but only for IPv6.', 5),
    ('saa', 'High-performing architectures', 'Which storage option supports concurrent POSIX file access from hundreds of Linux instances across Availability Zones?', 'EFS is a managed NFS file system reachable from multiple AZs at once. EBS Multi-Attach is limited to a small number of instances within a single AZ.', 6),
    ('saa', 'High-performing architectures', 'A static site in S3 must be served worldwide with low latency and HTTPS on a custom domain. What do you add?', 'CloudFront caches at edge locations and supports custom domains with ACM certificates. Transfer Acceleration speeds uploads to a bucket, not global delivery.', 7),
    ('saa', 'Cost-optimized architectures', 'Which two changes reduce the cost of a fleet running steady, predictable load 24/7? (Choose TWO)', 'Savings Plans discount committed steady usage, and right-sizing removes over-provisioned capacity. Spot is unsuitable for uninterruptible steady load, and monitoring adds cost.', 8),
    ('saa', 'Secure architectures', 'An account must prevent any IAM principal in a member account from disabling CloudTrail, regardless of their attached policies. What do you use?', 'SCPs set the maximum available permissions for accounts in an organization and cannot be overridden by identity policies inside the member account.', 9),
    ('saa', 'High-performing architectures', 'A DynamoDB table sees a very hot partition key during flash sales. Which change most directly relieves the throttling?', 'Throttling on a hot key is a key-distribution problem: sharding spreads writes across partitions, and DAX absorbs repeated reads. Streams and GSIs do not redistribute traffic on the base key.', 10),
    ('saa', 'Resilient architectures', 'A disaster recovery plan requires an RTO of minutes and an RPO of seconds for a multi-tier application. Which strategy?', 'Only active/active runs full capacity in both Regions with continuous replication, meeting an RTO of minutes and near-zero RPO. Warm standby still requires scale-up time.', 11),
    ('dva', 'Troubleshooting & optimization', 'A Lambda function intermittently times out while calling a downstream API. Which change addresses the failures without rewriting the integration?', 'Timeouts are a duration and transient-failure problem. Concurrency controls parallelism, and VPC placement usually adds latency rather than removing it.', 0),
    ('dva', 'Development with AWS services', 'Which DynamoDB feature lets an application react to item-level changes?', 'Streams emit an ordered change record per item modification, which Lambda can consume as an event source.', 1),
    ('dva', 'Security', 'A database password must be stored and rotated automatically. Which service?', 'Secrets Manager provides scheduled rotation through a rotation function. Parameter Store stores values but does not rotate them for you.', 2),
    ('dva', 'Troubleshooting & optimization', 'Which two changes reduce cold-start latency for a latency-sensitive Lambda function? (Choose TWO)', 'Provisioned concurrency keeps initialised environments warm, and more memory means proportionally more CPU, which shortens initialisation. DLQs and tracing do not affect startup.', 3),
    ('dva', 'Development with AWS services', 'An API Gateway REST API must return cached responses per user without reaching the backend. What do you enable?', 'API Gateway caching can include named request parameters or headers in the cache key, producing per-user cached responses.', 4),
    ('dva', 'Deployment', 'A new ECS task definition must be released with instant rollback. Which CodeDeploy deployment type?', 'Blue/green shifts traffic between two target groups, so rollback is a traffic shift rather than a redeploy.', 5),
    ('dva', 'Security', 'Which approach lets a browser upload directly to S3 without exposing credentials?', 'Presigned URLs carry a time-limited signature for a single operation, so no long-lived credentials reach the client.', 6),
    ('dva', 'Development with AWS services', 'A Step Functions state machine must run five checks in parallel and continue when all finish. Which state type?', 'A Parallel state runs a fixed set of branches concurrently and completes when every branch completes. Map iterates over a dynamic array.', 7),
    ('dva', 'Troubleshooting & optimization', 'Which two techniques help trace a slow request across API Gateway, Lambda and DynamoDB? (Choose TWO)', 'Active tracing captures the service segments and the X-Ray SDK adds subsegments for downstream SDK calls, giving an end-to-end trace.', 8),
    ('dva', 'Development with AWS services', 'An SQS consumer occasionally processes the same message twice. What is the correct fix?', 'Standard queues guarantee at-least-once delivery, so consumers must be idempotent; a visibility timeout shorter than processing causes redelivery.', 9),
    ('dva', 'Deployment', 'Which CloudFormation section lets one template deploy different instance sizes per environment?', 'Mappings hold keyed lookup tables, and Fn::FindInMap resolves the value using a parameter such as the environment name.', 10),
    ('dva', 'Troubleshooting & optimization', 'A Lambda function inside a VPC cannot reach DynamoDB. Which change resolves it without a NAT gateway?', 'Gateway endpoints route traffic to DynamoDB and S3 over the AWS network from private subnets, with no NAT required.', 11),
    ('ace', 'Access & security', 'Which resource hierarchy level should carry an IAM policy that must apply to every project in a department?', 'Folders group projects for a department, and IAM policies set on a folder are inherited by every project inside it.', 0),
    ('ace', 'Planning & configuring', 'You need a managed relational database with automatic failover to a second zone. Which product?', 'Cloud SQL HA keeps a standby in another zone with automatic failover. Firestore and Bigtable are non-relational.', 1),
    ('ace', 'Setting up a cloud environment', 'Which two commands report the active gcloud configuration? (Choose TWO)', 'config list prints the active configuration''s properties, and gcloud info includes the active account, project and configuration path.', 2),
    ('ace', 'Planning & configuring', 'A batch job tolerates interruption and must cost as little as possible on Compute Engine. What do you use?', 'Spot VMs offer the deepest discount in exchange for possible preemption, which this workload tolerates.', 3),
    ('ace', 'Planning & configuring', 'Which storage class fits objects read on average once a month with millisecond access?', 'Nearline targets data accessed less than once a month while still serving requests with millisecond latency.', 4),
    ('ace', 'Access & security', 'A GKE workload needs access to a Cloud Storage bucket with no key files. What do you configure?', 'Workload Identity binds a Kubernetes service account to a Google service account, so pods receive short-lived credentials.', 5),
    ('ace', 'Deploying & implementing', 'Which command deploys a container image to Cloud Run allowing unauthenticated access?', 'gcloud run deploy takes the image and the --allow-unauthenticated flag grants the invoker role to all users.', 6),
    ('ace', 'Setting up a cloud environment', 'Two teams must share one VPC while keeping separate projects and billing. Which feature?', 'Shared VPC lets service projects use subnets from a central host project while keeping their own IAM and billing.', 7),
    ('ace', 'Ensuring successful operation', 'Which two steps set a budget alert on a project''s spend? (Choose TWO)', 'Budgets are defined on the billing account with a scope, and threshold rules drive the notifications. Quotas cap usage but are not budget alerts.', 8),
    ('ace', 'Deploying & implementing', 'A Compute Engine instance must be reachable by name from other instances in the VPC. What provides this?', 'Compute Engine provides internal DNS names for instances inside the network automatically.', 9),
    ('ace', 'Ensuring successful operation', 'Which log tells you who deleted a Cloud Storage bucket?', 'Admin Activity audit logs record configuration and metadata changes, including resource deletions, with the caller identity.', 10),
    ('ace', 'Deploying & implementing', 'A managed instance group must add VMs when average CPU exceeds 60%. What do you configure?', 'Autoscaling policies scale the group against a target metric such as average CPU utilisation.', 11),
    ('pca', 'Solution design', 'A globally distributed application needs a relational database with strong consistency and horizontal write scaling. Which service?', 'Spanner is the managed option that combines external consistency with horizontal scale across regions. Cloud SQL and AlloyDB scale writes vertically.', 0),
    ('pca', 'Security & compliance', 'Which approach limits the blast radius of a compromised service account in a large organization?', 'Least privilege at the smallest workable scope, with impersonation and short-lived tokens instead of downloaded keys, contains the damage of a leak.', 1),
    ('pca', 'Solution design', 'An on-premises data centre needs private, high-bandwidth connectivity to a VPC with an availability SLA. What do you recommend?', 'Dedicated Interconnect provides a private physical connection into Google''s network with an availability SLA. Peering reaches public Google services and carries no VPC SLA.', 2),
    ('pca', 'Reliability & operations', 'Which two practices support a recovery point objective under one minute for a critical Cloud SQL database? (Choose TWO)', 'Point-in-time recovery and a continuously replicating cross-region replica both bound data loss to seconds. Nightly or weekly exports imply hours or days of loss.', 3),
    ('pca', 'Security & compliance', 'A regulated workload must keep encryption keys under customer control in an on-premises HSM. Which option?', 'Cloud EKM lets Google Cloud services use keys held in an external key management system the customer operates.', 4),
    ('pca', 'Reliability & operations', 'Traffic must shift gradually from a monolith to a rewritten service, rolling back automatically on error-rate spikes. Which pattern?', 'A canary exposes a small traffic share first, and tying promotion to error-budget burn gives an automatic rollback signal.', 5),
    ('pca', 'Security & compliance', 'Which resource hierarchy level should carry an IAM policy that must apply to every project in a department?', 'Folders group projects for a department, and IAM policies set on a folder are inherited by every project inside it.', 6),
    ('pca', 'Migration & modernisation', 'A lift-and-shift migration of 200 VMware VMs must minimise downtime and application changes. Which tool leads?', 'Migrate to Virtual Machines replicates running VMs and cuts over with minimal downtime, without re-architecting the applications.', 7),
    ('pca', 'Reliability & operations', 'Which two signals belong in an SLO for a user-facing API? (Choose TWO)', 'SLOs measure the user''s experience: availability and latency. CPU, deploy frequency and restarts are internal signals, useful for diagnosis rather than as objectives.', 8),
    ('pca', 'Solution design', 'An analytics team needs ad-hoc SQL over 500 TB without managing infrastructure, billed by query. Which service?', 'BigQuery is the serverless analytical warehouse with on-demand per-query pricing and no cluster to operate.', 9),
    ('pca', 'Security & compliance', 'A company must guarantee that data for EU customers never leaves EU regions. Which control enforces this?', 'The location-restriction organization policy prevents resource creation outside allowed regions. VPC Service Controls limit data exfiltration paths but do not pin resource location.', 10),
    ('pca', 'Solution design', 'Which design keeps a stateless web tier available during a full zone outage in one region?', 'Regional managed instance groups spread instances across zones, and the load balancer routes away from the failed zone automatically.', 11),
    ('cka', 'Cluster architecture & installation', 'Which command drains a node for maintenance while evicting pods managed by controllers?', 'drain cordons the node and evicts its pods. --ignore-daemonsets is required because DaemonSet pods are not evicted by their controller.', 0),
    ('cka', 'Troubleshooting', 'A pod stays in Pending. Which two causes are consistent with that state? (Choose TWO)', 'Pending means the pod is not yet scheduled or is waiting on a resource such as a PVC. Image-pull failures, probe failures and exits all happen after scheduling.', 1),
    ('cka', 'Cluster architecture & installation', 'Where does a kubeadm cluster keep static pod manifests for control-plane components?', 'The kubelet watches /etc/kubernetes/manifests and runs the API server, scheduler, controller manager and etcd as static pods from it.', 2),
    ('cka', 'Cluster architecture & installation', 'You must back up cluster state before an upgrade. Which component do you snapshot?', 'etcd holds all cluster state, and etcdctl snapshot save is the supported backup mechanism.', 3),
    ('cka', 'Cluster architecture & installation', 'Which pair grants a set of permissions to a service account within a single namespace?', 'Roles are namespaced, and a RoleBinding binds one to a subject inside that namespace. ClusterRoles are cluster-scoped.', 4),
    ('cka', 'Services & networking', 'A ClusterIP Service has no endpoints. What is the most likely cause?', 'Endpoints come from pods whose labels match the selector and that pass readiness. A label mismatch leaves the endpoint list empty.', 5),
    ('cka', 'Cluster architecture & installation', 'Which upgrade order does kubeadm require?', 'The control plane is upgraded first because kubelets must not be newer than the API server.', 6),
    ('cka', 'Storage', 'Which two objects are required for a pod to use dynamically provisioned block storage? (Choose TWO)', 'Dynamic provisioning creates the PersistentVolume for you from the StorageClass named in the claim, so no manual PV is needed.', 7),
    ('cka', 'Workloads & scheduling', 'A DaemonSet pod must run on control-plane nodes that carry a NoSchedule taint. What do you add?', 'Taints repel pods unless the pod tolerates them. A nodeSelector targets nodes but does not overcome a taint.', 8),
    ('cka', 'Troubleshooting', 'Which command shows the logs of the previous container instance after a crash loop?', '--previous reads the log of the last terminated container instance, which is where the cause of the crash appears.', 9),
    ('cka', 'Services & networking', 'Pods in namespace ''app'' must accept traffic only from pods in namespace ''edge''. Which object do you create?', 'NetworkPolicies select the allowed sources; a namespaceSelector restricts ingress to pods in the named namespace, assuming the CNI enforces policy.', 10),
    ('cka', 'Troubleshooting', 'kubectl reports ''The connection to the server was refused'' on a control-plane node. Which two checks come first? (Choose TWO)', 'A refused connection means the API server is not listening. Checking the kubelet that runs the static pod and the container itself locates the failure.', 11)
) as v(cert_slug, domain_name, body, explain, sort_order)
join certifications c on c.slug = v.cert_slug
join domains d on d.certification_id = c.id and d.name = v.domain_name;
